Method.Source:
private void whileSelectUpdateVSUpdateRecordset()
{
    //aqui si ejecutaran el metodo update
    RRBAuthorTable authorTable;

    ttsbegin;
    while select forupdate authorTable
        where authorTable.IsDead == NoYes::No
        && authorTable.DeathDate > dateNull()
    {
        authorTable.DeathDate = dateNull();
        //no llamos al validate write, porque estamos havciendo identico al update recordset, pero se debería hacer
        authorTable.update();
    }
    ttscommit;

    ttsbegin;
    update_recordset authorTable
        setting DeathDate = dateNull()
        where authorTable.IsDead == NoYes::No
        && authorTable.DeathDate > dateNull();
    ttscommit;
}
